int[] intArray = {5, 10, 12, 8};

public static int largest(int[] list, int startIndex, int lastIndex) {
    if (startIndex == lastIndex) {
        return list[startIndex]; // base case: only one element left
    } else {
        int max = largest(list, startIndex + 1, lastIndex);
        if (list[startIndex] >= max) {
            return list[startIndex];
        } else {
            return max;
        }
    }
}
// largest(intArray, 0, 3) returns 12
